Qualtrics.SurveyEngine.addOnReady(function () {
  this.hideNextButton();
  var self = this;
  var done = false;
  var debugLog = [];

  function log(msg) {
    debugLog.push(msg);
    Qualtrics.SurveyEngine.setEmbeddedData("ranking_debug",
      debugLog.join(" | "));
  }

  function parseNum(raw) {
    if (raw === null || raw === undefined) return NaN;
    raw = String(raw).trim().replace(",", ".");
    var v = parseFloat(raw);
    return Number.isFinite(v) ? v : NaN;
  }

  function nearlyEqual(a, b, eps) {
    return Math.abs(a - b) <= eps;
  }

  function shuffle(arr) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
    }
    return arr;
  }

  try {
    var eps = 1e-9;

    var rawThreat = "${e://Field/meanscore_threat}";
    var rawAband  = "${e://Field/meanscore_aband}";
    var rawFear   = "${e://Field/meanscore_fear}";
    var rawSuper  = "${e://Field/meanscore_super}";
    log("RAW: t=" + rawThreat + " a=" + rawAband +
        " f=" + rawFear + " s=" + rawSuper);

    var scores = {
      threat: parseNum(rawThreat),
      aband:  parseNum(rawAband),
      fear:   parseNum(rawFear),
      super:  parseNum(rawSuper)
    };

    log("PARSED: t=" + scores.threat + " a=" + scores.aband +
        " f=" + scores.fear + " s=" + scores.super);

    var keys = Object.keys(scores);

    var allValid = keys.every(function (k) {
      return Number.isFinite(scores[k]);
    });
    Qualtrics.SurveyEngine.setEmbeddedData("ranking_valid",
      allValid ? "1" : "0");

    if (!allValid) {
      log("ABORT: invalid scores");
      self.showNextButton();
      return;
    }

    var sorted = keys.slice().sort(function (a, b) {
      return scores[a] - scores[b];
    });
    log("SORTED: " + sorted.join(","));

    var compRanks = {};
    for (var i = 0; i < sorted.length; i++) {
      var rank = i + 1;
      for (var j = 0; j < i; j++) {
        if (nearlyEqual(scores[sorted[j]], scores[sorted[i]], eps)) {
          rank = compRanks[sorted[j]];
          break;
        }
      }
      compRanks[sorted[i]] = rank;
    }

    var groups = [];
    var currentGroup = [sorted[0]];
    for (var i = 1; i < sorted.length; i++) {
      if (nearlyEqual(scores[sorted[i]], scores[sorted[i - 1]], eps)) {
        currentGroup.push(sorted[i]);
      } else {
        groups.push(shuffle(currentGroup));
        currentGroup = [sorted[i]];
      }
    }
    groups.push(shuffle(currentGroup));

    var finalOrder = [];
    for (var g = 0; g < groups.length; g++) {
      for (var k = 0; k < groups[g].length; k++) {
        finalOrder.push(groups[g][k]);
      }
    }

    var forcedRanks = {};
    var groupLabels = {};
    for (var i = 0; i < finalOrder.length; i++) {
      forcedRanks[finalOrder[i]] = i + 1;
      groupLabels[finalOrder[i]] = (i < 2) ? "bottom" : "top";
    }

    // ── NEW: Map subscale keys to show_ field names ──
    var showMap = {
      threat: "show_threat_high",
      aband:  "show_aband_high",
      fear:   "show_fear_high",
      super:  "show_superior_high"
    };

    keys.forEach(function (s) {
      Qualtrics.SurveyEngine.setEmbeddedData("rank_" + s,
        String(compRanks[s]));
      Qualtrics.SurveyEngine.setEmbeddedData("forced_rank_" + s,
        String(forcedRanks[s]));
      Qualtrics.SurveyEngine.setEmbeddedData("group_" + s,
        groupLabels[s]);
      // ── NEW: Set show_ flags (1 for top, 0 for bottom) ──
      Qualtrics.SurveyEngine.setEmbeddedData(showMap[s],
        groupLabels[s] === "top" ? "1" : "0");
    });

    log("DONE: comp=" + JSON.stringify(compRanks) +
        " forced=" + JSON.stringify(forcedRanks) +
        " groups=" + JSON.stringify(groupLabels));

    done = true;
    setTimeout(function () { self.clickNextButton(); }, 0);

  } catch (e) {
    log("ERROR: " + e.message);
    Qualtrics.SurveyEngine.setEmbeddedData("ranking_valid", "0");
    self.showNextButton();
  }

  setTimeout(function () {
    if (!done) {
      log("TIMEOUT: safety net triggered");
      self.showNextButton();
    }
  }, 3000);
});

